class Post:
    def __init__(self, likes=0):
        if likes < 0:
            raise ValueError("点赞不能为负")
        self.likes = likes
        self.tags = []  # 每个实例各有一个列表

    def label(self):
        return f"{self.likes} 赞"

class FeaturedPost(Post):
    def __init__(self, likes, reason):
        super().__init__(likes)
        self.reason = reason

    def label(self):
        return f"精选：{super().label()}"

a, b = Post(12), Post(8)
a.tags.append("校园")
print(a.tags, b.tags)
