# 保存为 test_counts.py，安装 pytest 后运行 python -m pytest -q
import pytest

def parse_count(raw):
    value = int(raw)
    if value < 0:
        raise ValueError("计数不能为负")
    return value

@pytest.mark.parametrize("raw, expected", [("0", 0), ("12", 12)])
def test_valid(raw, expected):
    assert parse_count(raw) == expected

@pytest.mark.parametrize("raw", ["", "abc", "-1"])
def test_invalid(raw):
    with pytest.raises(ValueError):
        parse_count(raw)

def test_file(tmp_path):
    path = tmp_path / "count.txt"
    path.write_text("12", encoding="utf-8")
    assert parse_count(path.read_text(encoding="utf-8")) == 12

