def rows_from_response(payload):
    if not isinstance(payload.get("items"), list):
        raise ValueError("缺少 items 列表")
    rows = []
    for item in payload["items"]:
        count = item.get("stargazers_count")
        if type(count) is not int or count < 0:
            raise ValueError("星标数不合法")
        rows.append((item["full_name"], count, item.get("description") or "暂无说明"))
    return rows

print(rows_from_response({"items": [{"full_name": "demo/tool", "stargazers_count": 12, "description": None}]}))
try:
    rows_from_response({"message": "rate limited"})
except ValueError as exc:
