from functools import wraps

def trace(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        result = fn(*args, **kwargs)
        print(f"{fn.__name__} 完成")
        return result
    return wrapper

@trace
def total(values):
    return sum(values)

